import {runSolidityTests} from '../../scripts/test-solidity.mjs';import {writeFileSync} from 'node:fs';
const names=['reasonBytes','reasonOfBranch','emptyData','customSelector','customData','reasonPastCustom','externalReason','externalData','customSymbolic','panicData'];
const reports=[];
for(const name of names){const start=Date.now();const options={build:false,contract:'RevertData',function:name};const report=runSolidityTests(['tests/solc/RevertData.sol'],options);const row=report.results.find(r=>r.function===name);const ok=!report.errors.length&&row?.status==='proved';reports.push({name,options,seconds:(Date.now()-start)/1000,ok,report});writeFileSync('tests/upstream/group05/revert-properties.json',JSON.stringify({caveat:'The original full-contract test remains wall-time blocked. These are all ten original asserted properties, individually selected with the same proof and timeout limits; no expected verdict changed.',reports},null,2)+'\n');console.log(name,ok,row?.status);}
if(reports.some(r=>!r.ok))process.exitCode=1;
